using System;

// PROGRAM: Eksperimen Interface dan Explicit Implementation
public interface ICustomerNotifier
{
    void Notify(string message);
}

public interface IInternalAuditLogger
{
    void Notify(string message); // Nama method sama persis!
}

public class SecurityAlertSystem : ICustomerNotifier, IInternalAuditLogger
{
    // 1. Implementasi ICustomerNotifier
    void ICustomerNotifier.Notify(string message)
    {
        Console.WriteLine($"[SMS KE NASABAH] Peringatan: {message}");
    }

    // 2. Implementasi IInternalAuditLogger
    void IInternalAuditLogger.Notify(string message)
    {
        Console.WriteLine($"[SIEM AUDIT LOG] Internal Event: {message} | Timestamp: {DateTime.UtcNow}");
    }
}

public class Program
{
    public static void Main()
    {
        var system = new SecurityAlertSystem();

        // Panggilan melalui interface spesifik
        ICustomerNotifier customerChannel = system;
        customerChannel.Notify("Percobaan login mencurigakan terdeteksi.");

        IInternalAuditLogger auditChannel = system;
        auditChannel.Notify("Auth failure from IP 192.168.1.100");
    }
}

