using System;

public interface IPaymentChannel
{
    string Process(decimal amount);
}

public class QrisPayment : IPaymentChannel
{
    public string Process(decimal amount)
    {
        if (amount <= 0) throw new ArgumentException("Amount must be positive.");
        return $"[QRIS] Tagihan Rp {amount:N0} digenerate";
    }
}

public class VirtualAccountPayment : IPaymentChannel
{
    public string Process(decimal amount)
    {
        if (amount <= 0) throw new ArgumentException("Amount must be positive.");
        return $"[VA] Nomor VA Rp {amount:N0} aktif";
    }
}

public class Program
{
    public static void Main()
    {
        IPaymentChannel qris = new QrisPayment();
        IPaymentChannel va = new VirtualAccountPayment();

        Console.WriteLine(qris.Process(50000m));
        Console.WriteLine(va.Process(100000m));
    }
}
